import sys, os
from collections import Counter

_TBL = bytes(c + 32 if 65 <= c <= 90 else (c if 97 <= c <= 122 else 32) for c in range(256))

def count(data, i, j):
    return Counter(data[i:j].translate(_TBL).split())

def main():
    data = sys.stdin.buffer.read()
    n = len(data)
    nw = (os.cpu_count() or 1) * 2
    if n < (1 << 20) or nw < 2:
        c = count(data, 0, n)
    else:
        bounds = [0]
        for k in range(1, nw):
            j = n * k // nw
            while j < n and (97 <= data[j] <= 122 or 65 <= data[j] <= 90):
                j += 1
            bounds.append(j)
        bounds.append(n)
        pipes = []
        for k in range(nw):
            r, w = os.pipe()
            pid = os.fork()
            if pid == 0:
                os.close(r)
                d = count(data, bounds[k], bounds[k + 1])
                out = b"\n".join(b"%s %d" % kv for kv in d.items())
                with os.fdopen(w, 'wb') as f:
                    f.write(out)
                os._exit(0)
            os.close(w)
            pipes.append((pid, r))
        c = {}
        g = c.get
        for pid, r in pipes:
            with os.fdopen(r, 'rb') as f:
                txt = f.read()
            os.waitpid(pid, 0)
            for line in txt.split(b"\n"):
                if line:
                    w_, v = line.split(b" ")
                    c[w_] = g(w_, 0) + int(v)
    top = sorted(c.items(), key=lambda kv: (-kv[1], kv[0]))[:10]
    sys.stdout.write("".join(f"{w.decode()} {n}\n" for w, n in top))

if __name__ == "__main__":
    main()

