import sys, os, stat
from collections import Counter

_TBL = bytes(c + 32 if 65 <= c <= 90 else (c if 97 <= c <= 122 else 32) for c in range(256))

def count(data):
    return Counter(data.translate(_TBL).split())

def isalpha(b):
    return 97 <= b <= 122 or 65 <= b <= 90

def main():
    fd = sys.stdin.fileno()
    try:
        st = os.fstat(fd)
        regular = stat.S_ISREG(st.st_mode)
    except OSError:
        regular = False
    nw = (os.cpu_count() or 1) * 2
    if regular:
        n = st.st_size
        data = None
    else:
        data = sys.stdin.buffer.read()
        n = len(data)
    if n < (1 << 20) or nw < 2:
        if data is None:
            data = sys.stdin.buffer.read()
        c = count(data)
    else:
        pipes = []
        for k in range(nw):
            r, w = os.pipe()
            pid = os.fork()
            if pid == 0:
                os.close(r)
                i = n * k // nw
                j = n * (k + 1) // nw
                if data is None:
                    # adjust boundaries: extend forward past partial word at both ends
                    if i > 0:
                        probe = os.pread(fd, 256, i)
                        off = 0
                        while off < len(probe) and isalpha(probe[off]):
                            off += 1
                        i += off
                    if j < n:
                        probe = os.pread(fd, 256, j)
                        off = 0
                        while off < len(probe) and isalpha(probe[off]):
                            off += 1
                        j += off
                    chunk = b""
                    parts = []
                    pos = i
                    while pos < j:
                        b = os.pread(fd, j - pos, pos)
                        if not b:
                            break
                        parts.append(b)
                        pos += len(b)
                    chunk = b"".join(parts)
                else:
                    while i < n and isalpha(data[i]):
                        i += 1
                    while j < n and isalpha(data[j]):
                        j += 1
                    chunk = data[i:j]
                d = count(chunk)
                out = b"\n".join(b"%s %d" % kv for kv in d.items())
                with os.fdopen(w, 'wb') as f:
                    f.write(out)
                os._exit(0)
            os.close(w)
            pipes.append((pid, r))
        c = {}
        g = c.get
        for pid, r in pipes:
            with os.fdopen(r, 'rb') as f:
                txt = f.read()
            os.waitpid(pid, 0)
            for line in txt.split(b"\n"):
                if line:
                    w_, v = line.split(b" ")
                    c[w_] = g(w_, 0) + int(v)
    top = sorted(c.items(), key=lambda kv: (-kv[1], kv[0]))[:10]
    sys.stdout.write("".join(f"{w.decode()} {n}\n" for w, n in top))

if __name__ == "__main__":
    main()
